<?php
function adminDescription(string $table): string {return match($table){'articles'=>'콘텐츠를 검색하고 게시 상태와 노출 일정을 관리합니다.','campaigns'=>'모집 일정부터 응모·선정·리뷰까지 체험단 운영 현황을 확인합니다.','applications'=>'신청 내용을 비교하고 모집 정원에 맞춰 체험단 참여자를 선정합니다.','reviews'=>'제출된 리뷰와 미션을 비교하고 승인 또는 보완을 요청합니다.','points'=>'회원별 포인트 변동과 확정된 거래 내역을 조회합니다.','reports'=>'신고 사유와 대상 원문을 확인하고 조치 결과를 기록합니다.','inquiries'=>'회원 문의를 확인하고 답변과 처리 이력을 관리합니다.','banners'=>'배너 문구·이미지·기간·노출 순서를 관리합니다.','members'=>'회원의 공개 활동과 계정 상태를 관리합니다.','checklist'=>'새 매매일지에 적용할 항목과 버전·표시 순서를 관리합니다.',default=>'검색 조건으로 대상을 찾고 관련 정보와 처리 결과를 확인합니다.'};}
function adminLogin(): void {echo '<div class="admin-login-brand">'.icon('shield-check').'<strong>주부테크 관리자</strong></div><h1>운영 센터 로그인</h1><p class="muted">콘텐츠·체험단·회원 운영을 한곳에서 관리합니다.</p><div class="admin-note">가상 데이터로 검토하는 관리자 데모입니다. 실제 인증·역할 권한과 운영 DB는 연결되어 있지 않습니다.</div>'.actionForm('admin_login',[],'관리자 데모 시작','button button--full').'<a class="text-button mt-16" href="/finance">사용자 서비스 바로가기 '.icon('external-link').'</a>';}
function adminPanelTitle(string $title,string $href='',string $label='전체 보기'): void {echo '<div class="admin-panel-title"><h2>'.e($title).'</h2>'.($href?'<a class="text-button" href="'.e($href).'">'.e($label).icon('chevron-right').'</a>':'').'</div>';}
function adminDashboard(): void {
 global $repo;$pending=count(array_filter($repo->all('applications'),fn($r)=>$r['selectionStatus']==='applied'));$reviews=count(array_filter($repo->all('reviews'),fn($r)=>$r['reviewStatus']==='pending'));$inquiries=count(array_filter($repo->all('inquiries'),fn($r)=>$r['status']==='pending'));$reports=count(array_filter($repo->all('reports'),fn($r)=>$r['status']==='pending'));
 echo '<section class="admin-panel admin-tasks">';adminPanelTitle('처리 대기 업무');echo '<div class="admin-task-grid">';foreach([['미답변 문의',$inquiries,'inquiries','pending','message-circle'],['미처리 신고',$reports,'reports','pending','shield-check'],['검수 대기 리뷰',$reviews,'reviews','pending','clipboard-check'],['선정 검토 응모',$pending,'applications','applied','users']] as [$label,$n,$table,$status,$icon])echo '<a href="/admin/'.$table.'?status='.$status.'" class="admin-task"><span>'.icon($icon).e($label).'</span><strong>'.number_format($n).'<small>건</small></strong><span class="admin-task-link">목록 확인 '.icon('chevron-right').'</span></a>';echo '</div></section>';
 echo '<div class="admin-stats">';foreach([['게시 중 콘텐츠',count(array_filter($repo->all('articles'),fn($a)=>$repo->visibleArticle($a))),'/admin/articles?status=published&visibility=visible'],['모집 중 체험단',count(array_filter($repo->all('campaigns'),fn($a)=>$repo->visibleCampaign($a)&&$repo->campaignState($a)==='open')),'/admin/campaigns?status=published&recruiting=open&exposure=visible'],['전체 회원',count($repo->all('members')),'/admin/members'],['사용 중 배너',count(array_filter($repo->all('banners'),fn($r)=>$r['enabled'])),'/admin/banners?enabled=1']] as [$label,$value,$url])echo '<a class="admin-stat" href="'.$url.'"><span>'.e($label).'</span><strong>'.number_format($value).'</strong>'.icon('arrow-up-right').'</a>';echo '</div>';
 echo '<div class="admin-columns"><section class="admin-panel">';adminPanelTitle('모집 중인 체험단','/admin/campaigns?recruiting=open');$rows=array_values(array_filter($repo->all('campaigns'),fn($c)=>$repo->campaignState($c)==='open'));echo '<div class="table-wrap"><table class="table"><caption class="sr-only">모집 중인 체험단 운영 현황</caption><thead><tr><th>체험단명</th><th>모집 마감</th><th class="number">응모 / 정원</th><th>관리</th></tr></thead><tbody>';foreach(array_slice($rows,0,5) as $c){$n=count(array_filter($repo->all('applications'),fn($a)=>$a['campaignId']===$c['id']));echo '<tr><td><a class="admin-title-link" href="/admin/campaigns/'.e($c['id']).'/edit">'.e($c['title']).'</a><small>'.e($c['brand']).'</small></td><td>'.dateLabel($c['recruitmentEndAt'],'m.d').'</td><td class="number">'.$n.' / '.$c['capacity'].'명</td><td><a class="text-button" href="/admin/applications?campaign='.e($c['id']).'">응모</a></td></tr>';}echo '</tbody></table></div></section><section class="admin-panel">';adminPanelTitle('최근 등록 콘텐츠','/admin/articles');foreach(array_slice(adminQueryRows('articles',[]),0,5) as $r)echo '<a class="admin-recent" href="/admin/articles/'.e($r['id']).'/edit"><span><strong>'.e($r['title']).'</strong><small>'.e(categoryName($r['categoryId'])).' · '.dateLabel($r['publishedAt'],'Y.m.d').'</small></span>'.badge(adminStatusLabel($r['status'])).'</a>';echo '</section></div>';
 echo '<section class="admin-panel mt-16">';adminPanelTitle('최근 운영 이력');$activity=array_slice(array_reverse($repo->all('activity')),0,6);if(!$activity)echo '<div class="admin-empty">아직 처리 이력이 없습니다. 관리 작업을 저장하면 이곳에 표시됩니다.</div>';foreach($activity as $a)echo '<div class="admin-history-row">'.icon('circle-check').'<span>'.e($a['text']).'</span><time>'.dateLabel($a['createdAt'],'Y.m.d H:i').'</time></div>';echo '</section><p class="admin-footnote">세션의 가상 데이터 기준 집계 · 기준 시각 '.$repo->now()->format('Y.m.d H:i').' KST · 비공개 매매 기록은 관리자에게 제공하지 않습니다.</p>';
}
function adminSearch(string $table,array $schema): void {
 global $repo;$statusField=adminStatusField($table);$statuses=match($table){'articles','campaigns','notices'=>['draft'=>'초안','published'=>'공개','hidden'=>'비공개'],'applications'=>['applied'=>'신청 완료','selected'=>'선정','not_selected'=>'미선정','cancelled'=>'취소'],'reviews'=>['pending'=>'검토 대기','revision'=>'보완 요청','approved'=>'승인','rejected'=>'반려'],'members'=>['active'=>'사용 중','suspended'=>'이용 정지'],'inquiries'=>['pending'=>'답변 대기','answered'=>'답변 완료'],'reports'=>['pending'=>'처리 대기','resolved'=>'처리 완료'],'posts','comments'=>['published'=>'공개','hidden'=>'숨김','deleted'=>'작성자 삭제'],'exchanges'=>['demo'=>'데모 신청','cancelled'=>'취소'],default=>[]};
 echo '<section class="admin-panel admin-search-panel" aria-labelledby="search-title"><div class="admin-panel-title"><h2 id="search-title">검색 조건</h2><span class="muted">조건을 조합해 필요한 항목을 찾으세요.</span></div><form id="admin-search" method="get" action="/admin/'.e($table).'" data-admin-search><div class="admin-filter-grid">';
 echo '<div class="admin-search-keyword"><div class="field"><label class="label" for="search-by">검색어</label><div class="admin-inline"><select class="select" id="search-by" name="search_by" aria-label="검색어 종류">';foreach(['all'=>'전체','title'=>'제목·명칭','id'=>'ID','member'=>'회원 닉네임'] as $k=>$v)echo '<option value="'.$k.'"'.(($_GET['search_by']??'all')===$k?' selected':'').'>'.$v.'</option>';echo '</select><input class="input" type="search" aria-label="검색어 입력" name="q" value="'.e($_GET['q']??'').'" placeholder="검색어를 입력하세요"></div></div></div>';
 if($statuses)echo selectField('status','상태',[''=>'전체']+$statuses,$_GET['status']??'');foreach(adminFilters($table) as $name=>[$label,$options])echo selectField($name,$label,[''=>'전체']+$options,$_GET[$name]??'');
 if(in_array($table,['applications','reviews']))echo selectField('campaign','체험단',[''=>'전체 체험단']+array_column($repo->all('campaigns'),'title','id'),$_GET['campaign']??'');
 if(in_array($table,['points','exchanges','inquiries','posts','comments','applications','reviews']))echo selectField('member','회원',[''=>'전체 회원']+array_column($repo->all('members'),'nickname','id'),$_GET['member']??'');
 $dates=adminDateFields($table);if($dates){echo '<div class="admin-date-filter"><div class="field"><label class="label" for="date-field">조회 기간</label><div class="admin-date-inputs"><select class="select" id="date-field" name="date_field" aria-label="날짜 기준">';foreach($dates as $k=>$label)echo '<option value="'.$k.'"'.(($_GET['date_field']??array_key_first($dates))===$k?' selected':'').'>'.e($label).'</option>';echo '</select><input class="input" type="date" name="from" aria-label="시작일" value="'.e($_GET['from']??'').'"> <span>~</span> <input class="input" type="date" name="to" aria-label="종료일" value="'.e($_GET['to']??'').'">';foreach([0=>'전체',7=>'7일',30=>'1개월',90=>'3개월'] as $days=>$label)echo '<button class="button button--neutral" type="button" data-quick-days="'.$days.'" data-today="'.$repo->now()->format('Y-m-d').'">'.$label.'</button>';echo '</div></div></div>';}
 echo '</div><div class="admin-search-actions"><button class="button" type="submit">'.icon('search').' 검색</button><a class="button button--neutral" href="/admin/'.$table.'">'.icon('rotate-ccw').' 초기화</a></div><input type="hidden" name="sort" value="'.e($_GET['sort']??'newest').'" data-query-sort><input type="hidden" name="per_page" value="'.e($_GET['per_page']??10).'" data-query-per></form></section>';
}
function adminResult(): void {
 $r=$_SESSION['adminResult']??null;unset($_SESSION['adminResult']);if(!$r)return;echo '<section class="admin-notice'.($r['failed']?' admin-notice--error':'').'" role="status"><strong>처리 결과: 성공 '.$r['success'].'건 · 제외 '.$r['excluded'].'건 · 실패 '.count($r['failed']).'건</strong><p>제외: 이미 같은 상태인 항목. 성공한 변경은 저장되었습니다.</p>';if($r['failed']){echo '<ul>';foreach($r['failed'] as $f)echo '<li><strong>'.e($f['id']).'</strong> — '.e($f['reason']).'</li>';echo '</ul><button type="button" class="button button--neutral" data-retry-ids="'.e(json_encode(array_column($r['failed'],'id'))).'">현재 페이지의 실패 항목만 다시 선택</button>';}echo '</section>';
}
function adminList(string $table): void {
 global $repo;require APP_PATH.'/admin-schema.php';if(!isset($adminSchemas[$table])){notFound();return;}if($table==='settings'){adminEdit('settings','site');echo '<section class="admin-panel mt-16">';adminPanelTitle('데모 데이터 관리');echo '<div class="p-16"><p class="mb-16">현재 가상 세션의 기록만 최초 상태로 초기화합니다.</p>'.actionForm('reset_demo',[],'데모 초기화','button button--neutral','현재 세션의 변경사항과 가상 기록을 초기화합니다. 계속할까요?').'</div></section>';return;}
 if(($_GET['export']??'')==='csv')adminExport($table);$schema=$adminSchemas[$table];adminResult();adminSearch($table,$schema);$rows=adminQueryRows($table,$_GET);$GLOBALS['adminCurrentList']='/admin/'.$table.($_GET?'?'.http_build_query($_GET):'');
 echo '<section class="admin-panel mt-16">';adminTable($table,$rows,$schema,$repo->all($table)[0]??[]);echo '</section>';
 if($table==='checklist')echo '<p class="admin-footnote">템플릿 수정은 새 일지에 적용됩니다. 과거 기록의 문구·버전·평가 결과는 보존됩니다.</p>';if($table==='points')echo '<p class="admin-footnote">확정 원장은 수정·삭제하지 않습니다. 수동 지급·차감 정책과 실제 지급 시스템은 미연동입니다.</p>';
}
function adminBack(string $table,?array $r=null): void {
 global $repo;$list=adminListUrl($table);echo '<div class="admin-detail-nav"><a class="button button--neutral" href="'.e($list).'">'.icon('arrow-left').' 목록으로</a><div class="row gap-8">';if($r){parse_str(parse_url($list,PHP_URL_QUERY)??'',$query);$rows=adminQueryRows($table,$query);$ids=array_column($rows,'id');$pos=array_search($r['id'],$ids,true);if($pos!==false){echo '<span class="muted">'.($pos+1).' / '.count($ids).'</span>';foreach([-1=>'이전',1=>'다음'] as $offset=>$label){$target=$ids[$pos+$offset]??null;echo $target?'<a class="button button--neutral" href="'.e(adminItemUrl($table,$target,isset($GLOBALS['adminSchemas'][$table]['fields']),$list)).'">'.$label.'</a>':'<button class="button button--neutral" type="button" disabled>'.$label.'</button>';}}}echo '</div></div>';
}
function adminEdit(string $table,string $id='new'): void {
 global $repo,$adminSchemas;require APP_PATH.'/admin-schema.php';if(!isset($adminSchemas[$table]['fields'])){notFound();return;}$id=$id==='new'?'':$id;$r=$id?$repo->find($table,$id):[];if($id&&!$r){notFound();return;}adminResult();adminBack($table,$r?:null);
 if($id){echo '<div class="admin-record-heading"><h2>'.e(adminRowName($r)).'</h2>';if(isset($r[adminStatusField($table)]))echo badge(adminStatusLabel((string)$r[adminStatusField($table)]));if(in_array($table,['articles','campaigns','notices']))echo '<a class="button button--neutral" target="_blank" rel="noopener" href="/admin/'.$table.'/'.e($id).'/preview">'.icon('eye').' 사용자 화면 미리보기</a>';echo '</div>';}
 if($table==='campaigns'&&$id){echo '<div class="admin-related">';foreach(['applications'=>'응모·선정','reviews'=>'리뷰 검수'] as $target=>$label)echo '<a class="button button--outline" href="/admin/'.$target.'?campaign='.e($id).'">'.$label.' '.icon('arrow-right').'</a>';echo '<span class="muted">정원 '.$r['capacity'].'명 · 선정 '.count(array_filter($repo->all('applications'),fn($a)=>$a['campaignId']===$id&&$a['selectionStatus']==='selected')).'명</span></div>';}
 if($table==='articles')$r['body']=implode("\n\n",array_map(fn($block)=>(($block['type']??'')==='heading'?'## ':'').($block['text']??''),$r['bodyBlocks']??[]));adminEditForm($table,$id,$r,$adminSchemas[$table]);
 if($id&&in_array($table,['articles','campaigns','notices','banners']))echo '<div class="admin-delete-area">'.actionForm('admin_delete',['id'=>$id,'table'=>$table,'expected'=>rowVersion($repo->find($table,$id)),'return'=>adminListUrl($table)],'항목 삭제','button button--danger','대상: '.adminRowName($r).' · 항목을 삭제합니다. 응모가 연결된 체험단은 삭제할 수 없으며 숨김을 사용해야 합니다.').'</div>';if($id)adminRecordHistory($table,$id);
}
function adminInfo(array $items): void {echo '<dl class="admin-info">';foreach($items as $k=>$v)echo '<div><dt>'.e($k).'</dt><dd>'.$v.'</dd></div>';echo '</dl>';}
function adminTextPanel(string $title,string $text): void {echo '<section class="admin-panel">';adminPanelTitle($title);echo '<div class="post post--flush admin-prose">'.nl2br(e($text)).'</div></section>';}
function adminRecordHistory(string $table,string $id): void {global $repo;$rows=array_reverse(array_values(array_filter($repo->all('adminHistory'),fn($r)=>$r['table']===$table&&$r['targetId']===$id)));echo '<section class="admin-panel mt-16">';adminPanelTitle('처리 이력 · 내부 기록');if(!$rows)echo '<div class="admin-empty">기록된 처리 이력이 없습니다. 이후 변경부터 기록합니다.</div>';foreach($rows as $r)echo '<div class="admin-history-row"><strong>'.e($r['action']).'</strong><span>'.e($r['reason']).'</span><small>'.e($r['operator']).' · '.dateLabel($r['createdAt'],'Y.m.d H:i').'</small></div>';echo '</section>';}
function adminOperationForm(string $table,array $r): void {if(!adminOps($table))return;formStart('admin_operate',['table'=>$table,'id'=>$r['id'],'expected'=>rowVersion($r),'return'=>$_SERVER['REQUEST_URI']],'class="admin-panel mt-16" data-operation-form data-admin-confirm');adminPanelTitle('상태 변경');echo '<div class="admin-form-grid p-16">'.selectField('op','변경할 상태',adminOps($table)).field('reason','처리 사유 · 내부 기록','','textarea',['rows'=>2]).'</div><div class="admin-form-footer"><button class="button">처리 내용 확인</button><span class="help">최신 상태와 처리 가능 여부를 서버에서 확인합니다.</span></div></form>';}
function adminDetail(string $table,string $id): void {
 global $repo;require APP_PATH.'/admin-schema.php';if(!isset($adminSchemas[$table])){notFound();return;}$r=$repo->find($table,$id);if(!$r){notFound();return;}adminResult();adminBack($table,$r);$ret=$_SERVER['REQUEST_URI'];echo '<div class="admin-record-heading"><h2>'.e(adminRowName($r)).'</h2>'.(isset($r[adminStatusField($table)])?badge(adminStatusLabel((string)$r[adminStatusField($table)])):'').'<small class="muted">ID '.e($id).'</small></div>';
 switch($table){
 case 'applications':
  $c=$repo->find('campaigns',$r['campaignId']);$m=$repo->find('members',$r['memberId']);$selected=count(array_filter($repo->all('applications'),fn($a)=>$a['campaignId']===$c['id']&&$a['selectionStatus']==='selected'));
  echo '<div class="admin-review-grid"><div>';adminTextPanel('신청 사유',$r['answers']['reason']);foreach($r['answers']['extra']??[] as $i=>$answer)echo '<section class="admin-panel mt-16"><div class="admin-panel-title"><h2>'.e($c['questions'][$i]??'추가 답변').'</h2></div><div class="p-16">'.nl2br(e($answer)).'</div></section>';echo '</div><div class="admin-panel">';adminPanelTitle('선정 판단 정보');adminInfo(['체험단'=>'<a class="admin-title-link" href="/admin/campaigns/'.e($c['id']).'/edit">'.e($c['title']).'</a>','신청자'=>e($m['nickname']),'연락처'=>e($m['maskedContact']),'신청일'=>dateLabel($r['appliedAt'],'Y.m.d H:i'),'활동 채널'=>!empty($r['answers']['channelUrl'])?'<a class="admin-title-link" target="_blank" rel="noopener noreferrer" href="'.e($r['answers']['channelUrl']).'">채널 원본 열기 '.icon('external-link').'</a>':'설문','모집 정원'=>$c['capacity'].'명 / 현재 선정 '.$selected.'명','필수 동의 / 선택 동의'=>($r['consentRecords']['required']?'동의':'미동의').' / '.($r['consentRecords']['optional']?'동의':'미동의')]);
  if($r['selectionStatus']!=='cancelled'&&!$repo->review($id)){formStart('admin_select',['id'=>$id,'expected'=>$r['selectionStatus'],'expectedVersion'=>rowVersion($r),'return'=>$ret],'class="p-16 stack" data-admin-confirm');echo selectField('selectionStatus','선정 결과',['applied'=>'신청 완료 · 선정 해제','selected'=>'선정','not_selected'=>'미선정'],$r['selectionStatus']).'<p>모집 '.$c['capacity'].'명 · 기존 선정 '.$selected.'명 · 이번 처리 1명. 정원 초과는 저장할 수 없습니다.</p><button class="button">응모 결과 저장</button></form>';}else echo '<div class="admin-note">취소 또는 리뷰 제출 이후에는 선정 결과를 변경할 수 없습니다.</div>';echo '<p class="admin-footnote">선정 저장과 앱 내 데모 알림만 반영합니다. 외부 문자·이메일 발송은 미연동입니다.</p></div></div>';break;
 case 'reviews':
  $app=$repo->find('applications',$r['applicationId']);$c=$repo->find('campaigns',$app['campaignId']);echo '<div class="admin-review-grid"><div>';adminTextPanel('제출 리뷰',$r['content']);echo '<div class="admin-related">'.e($repo->find('members',$app['memberId'])['nickname']).' · '.dateLabel($r['submittedAt'],'Y.m.d H:i');if($r['url'])echo '<a class="button button--outline" target="_blank" rel="noopener noreferrer" href="'.e($r['url']).'">리뷰 원본 확인 '.icon('external-link').'</a>';echo '</div></div><section class="admin-panel">';adminPanelTitle('체험단 미션과 검수 기준');echo '<div class="admin-prose post"><h3>'.e($c['title']).'</h3><ul>';foreach($c['missions'] as $mission)echo '<li>'.e($mission).'</li>';echo '</ul><p>후기 마감: '.dateLabel($c['reviewDueAt'],'Y.m.d H:i').'</p></div></section></div>';
  formStart('admin_review',['id'=>$id,'expected'=>rowVersion($r),'return'=>$ret],'class="admin-panel mt-16" data-dirty-form data-admin-confirm');adminPanelTitle('검수 결과');echo '<div class="admin-form-grid p-16">'.selectField('reviewStatus','검수 상태',['pending'=>'검토 대기','approved'=>'승인','revision'=>'보완 요청','rejected'=>'반려'],$r['reviewStatus']).field('feedback','사용자에게 전달할 보완·반려 사유',$r['feedback'],'textarea',['rows'=>3]).'</div><div class="admin-form-footer"><button class="button">검토 결과 저장</button><span class="help">보완·반려 시 사유 필수 · 앱 내 알림만 생성</span></div></form>';if(in_array($r['reviewStatus'],['approved','rejected']))echo '<div class="admin-note">확정된 검수를 개별 재처리하면 사용자에게 표시되는 결과가 변경됩니다. 제출물과 기존 이력을 확인해 주세요.</div>';adminReviewHistory($r);break;
 case 'inquiries':
  echo '<div class="admin-review-grid"><div>';adminTextPanel('회원 문의 원문',$r['body']);echo '<div class="admin-note">'.e($repo->find('members',$r['memberId'])['nickname']).' · '.dateLabel($r['createdAt'],'Y.m.d').' 접수</div></div>';formStart('admin_answer',['id'=>$id,'expected'=>rowVersion($r),'return'=>$ret],'class="admin-panel" data-dirty-form');adminPanelTitle($r['answer']?'답변 수정':'답변 작성');echo '<div class="p-16">'.field('answer','회원에게 전달되는 답변',$r['answer'],'textarea',['required'=>'required','rows'=>10]).'</div><div class="admin-form-footer"><button class="button">답변 저장</button><span class="help">저장 시 답변 완료로 반영됩니다.</span></div></form></div>';break;
 case 'reports':
  $post=$repo->find('posts',$r['postId']);echo '<div class="admin-review-grid"><div>';adminTextPanel('신고 사유',$r['body']);if($post){adminTextPanel('신고 대상 · '.($post['status']==='hidden'?'숨김':'공개').' 게시글',$post['title']."\n\n".$post['body']);echo '<a class="text-button" href="/admin/posts/'.e($post['id']).'">대상 게시글 상세 확인</a>';}echo '</div><section class="admin-panel">';adminPanelTitle('동일 대상 신고');$duplicates=array_values(array_filter($repo->all('reports'),fn($x)=>$x['postId']===$r['postId']));foreach($duplicates as $d)echo '<div class="admin-recent"><span>'.e($d['body']).'<small>'.e($d['id']).'</small></span>'.badge(adminStatusLabel($d['status'])).'</div>';echo '<p class="admin-footnote">이 신고 1건만 완료 처리합니다. 게시글 숨김은 해당 원문 전체에 적용됩니다.</p>';
  if($r['status']==='pending'){formStart('admin_report',['id'=>$id,'expected'=>rowVersion($r),'expectedTarget'=>$post?rowVersion($post):'','return'=>$ret],'class="p-16 stack" data-admin-confirm');echo selectField('reportAction','대상 조치',['none'=>'조치 없음 · 검토 기록','hide'=>'대상 게시글 숨김']).field('result','처리 사유 · 내부 기록','','textarea',['required'=>'required']).'<button class="button">조치 결과 저장</button></form>';}else echo '<div class="p-16">'.nl2br(e($r['result']??'')).'</div>';echo '</section></div>';break;
 case 'posts':case 'comments':
  if($table==='comments'){$post=$repo->find('posts',$r['postId']);if($post)adminTextPanel('댓글이 달린 원문',$post['title']."\n\n".$post['body']);}adminTextPanel($table==='posts'?'게시글 원문':'댓글 원문',($r['title']??'')."\n".$r['body']);if($table==='posts'){echo '<section class="admin-panel mt-16">';adminPanelTitle('관련 댓글');$comments=array_filter($repo->all('comments'),fn($c)=>$c['postId']===$id);if(!$comments)echo '<div class="admin-empty">등록된 댓글이 없습니다.</div>';foreach($comments as $c)echo '<a class="admin-recent" href="/admin/comments/'.e($c['id']).'"><span>'.e($c['body']).'</span>'.badge(adminStatusLabel($c['status'])).'</a>';echo '</section>';}echo '<p class="admin-footnote">공개 원문만 표시합니다. 연결된 비공개 매매 기록은 조회하지 않습니다. 작성자 삭제는 복원할 수 없습니다.</p>';adminOperationForm($table,$r);break;
 case 'members':
  echo '<section class="admin-panel">';adminPanelTitle('회원 운영 정보');adminInfo(['닉네임'=>e($r['nickname']),'연락처'=>e($r['maskedContact']),'가입일'=>dateLabel($r['joinedAt'],'Y.m.d'),'계정 상태'=>adminStatusLabel($r['accountStatus']),'포인트 잔액'=>number_format(array_sum(array_column(array_filter($repo->all('points'),fn($p)=>$p['memberId']===$id),'amount'))).' P']);echo '</section><div class="admin-related">';foreach(['points'=>'포인트 내역','exchanges'=>'교환 신청','inquiries'=>'문의','applications'=>'응모 이력'] as $target=>$label)echo '<a class="button button--outline" href="/admin/'.$target.'?member='.e($id).'">'.$label.'</a>';echo '</div><div class="admin-note">비공개 개인 매매일지는 접근할 수 없습니다. 연락처는 마스킹됩니다. 계정 상태는 데모 세션에 반영되며 실제 인증 차단은 미연동입니다.</div>';adminOperationForm($table,$r);break;
 case 'points':
  echo '<section class="admin-panel">';adminPanelTitle('포인트 원장');echo '<div class="admin-ledger-amount">'.($r['amount']>0?'+':'').number_format($r['amount']).'<small> P</small></div>';adminInfo(['회원'=>e($repo->find('members',$r['memberId'])['nickname']),'구분'=>$r['amount']>=0?'지급·적립':'사용·차감','사유'=>e($r['reason']),'처리일'=>dateLabel($r['createdAt'],'Y.m.d H:i'),'연결 교환'=>isset($r['exchangeId'])?'<a class="admin-title-link" href="/admin/exchanges/'.e($r['exchangeId']).'">'.e($r['exchangeId']).'</a>':'기존 내역']);echo '</section><div class="admin-note">확정 원장은 수정·삭제하지 않습니다. 실제 지급·정산은 미연동입니다.</div>';break;
 case 'exchanges':
  echo '<section class="admin-panel">';adminPanelTitle('교환 처리 단계');echo '<ol class="admin-steps"><li>데모 신청·차감</li><li>'.($r['status']==='cancelled'?'취소·반환 완료':'외부 발급 미연동').'</li></ol>';adminInfo(['교환 항목'=>e($r['title']),'회원'=>e($repo->find('members',$r['memberId'])['nickname']),'사용 포인트'=>isset($r['points'])?number_format($r['points']).' P':'연결 내역 확인 필요','신청일'=>dateLabel($r['createdAt'],'Y.m.d H:i'),'현재 단계'=>adminStatusLabel($r['status'])]);echo '</section><section class="admin-panel mt-16">';adminPanelTitle('연결 포인트 원장');$ledger=array_filter($repo->all('points'),fn($p)=>($p['exchangeId']??'')===$id);if(!$ledger)echo '<div class="admin-empty">연결 원장이 없는 기존 신청은 자동 반환할 수 없습니다.</div>';foreach($ledger as $p)echo '<div class="admin-recent"><span>'.e($p['reason']).'</span><strong>'.number_format($p['amount']).' P</strong></div>';echo '</section>';if($r['status']==='demo')adminOperationForm($table,$r);break;
 default:echo '<a class="button" href="'.e(adminItemUrl($table,$id,true)).'">편집하기</a>';
 }adminRecordHistory($table,$id);
}
function adminPreview(string $table,string $id): void {global $repo;$r=$repo->find($table,$id);if(!$r||!in_array($table,['articles','campaigns','notices'])){notFound();return;}echo '<div class="admin-note">저장된 데이터의 사용자 화면 미리보기 · 초안·숨김도 표시합니다.</div><iframe class="admin-preview-frame" title="저장된 사용자 화면 미리보기" src="/admin-user-preview/'.e($table).'/'.e($id).'"></iframe>';}
